INSERT INTO games (id, slug, title, era, genre, description, controls, ai_credit, track, status, featured, play_count, score_label, score_cap, html_path, art_url, created_by, created_at, data_origin) VALUES ('reconstructed:boulder-rush', 'boulder-rush', 'Boulder Rush', 'DOS', 'Puzzle', 'Miner digging tunnels past boulders and gems', 'Arrows or WASD to dig and move. P pauses. Touch controls are available.', 'AI agents', 'B', 'published', 0, 0, 'Score', 1000000, '/games/boulder-rush.html', '/assets/games/boulder-rush.png', NULL, '2026-11-08T00:00:00.000Z', 'reconstructed');
INSERT INTO games (id, slug, title, era, genre, description, controls, ai_credit, track, status, featured, play_count, score_label, score_cap, html_path, art_url, created_by, created_at, data_origin) VALUES ('reconstructed:brickstorm', 'brickstorm', 'Brickstorm', 'Arcade', 'Brick breaker', 'Three boards of workshop ceramics behind a paddle. The ball speeds up with every break, firebrick takes three hits and basalt takes four, and eight powerups arrive from a shuffled bag so a long run sees all of them. Clear a board without dropping a ball for the bonus, and remember the shield only saves you once.', 'Arrows/AD or the mouse slide the paddle, Space/W/Up launches and frees a caught ball. P pause, M mute. Touch: slide pads left, LAUNCH right.', 'AI agents', 'A', 'published', 0, 0, 'Score', 50000, NULL, '/assets/games/brickstorm.png', NULL, '2026-11-08T00:00:00.000Z', 'reconstructed');
INSERT INTO games (id, slug, title, era, genre, description, controls, ai_credit, track, status, featured, play_count, score_label, score_cap, html_path, art_url, created_by, created_at, data_origin) VALUES ('reconstructed:flap-hero', 'flap-hero', 'Flap Hero', 'Mobile', 'Flying', 'Plump bird flying between tall pillars', 'Space, click or tap to flap. P pauses, M mutes.', 'AI agents', 'B', 'published', 0, 0, 'Score', 1000000, '/games/flap-hero.html', '/assets/games/flap-hero.png', NULL, '2026-11-08T00:00:00.000Z', 'reconstructed');
INSERT INTO games (id, slug, title, era, genre, description, controls, ai_credit, track, status, featured, play_count, score_label, score_cap, html_path, art_url, created_by, created_at, data_origin) VALUES ('reconstructed:gem-columns', 'gem-columns', 'Gem Columns', 'Genesis', 'Falling-block puzzle', 'A falling-triad puzzle down three wells: the artisan foundry, the conservatory, and the archaeological archive. Ten gem identities in all, six per well. Cycle the triad as it drops, line up three of one gem across, down, or on either diagonal, and clear the well''s quota to move on. Cascades pay triple, then six times, long lines earn extra, and finishing a well fast earns a speed bonus.', 'Arrows/AD move, Down/S soft-drops, Space/W/Up cycles the triad. P pause, M mute. Touch: move pads left, CYCLE and DROP right.', 'AI agents', 'A', 'published', 0, 0, 'Score', 60000, NULL, '/assets/games/gem-columns.png', NULL, '2026-11-08T00:00:00.000Z', 'reconstructed');
INSERT INTO games (id, slug, title, era, genre, description, controls, ai_credit, track, status, featured, play_count, score_label, score_cap, html_path, art_url, created_by, created_at, data_origin) VALUES ('reconstructed:hyper-circuit', 'hyper-circuit', 'Hyper Circuit', 'SNES', 'Racing', 'Anti-gravity racing over sun-baked flats. Three original circuits, four rivals, a shield that boost and rail scrapes both feed on, and a translucent ghost that learns your best lap and dares you to beat it.', 'Arrows/WASD steer, accelerate and brake. Space or Shift to boost (spends shield). P pause, M mute. Touch: drag to steer, hold to accelerate, BOOST button.', 'AI agents', 'A', 'published', 0, 0, 'Score', 40000, NULL, '/assets/games/hyper-circuit.png', NULL, '2026-11-08T00:00:00.000Z', 'reconstructed');
INSERT INTO games (id, slug, title, era, genre, description, controls, ai_credit, track, status, featured, play_count, score_label, score_cap, html_path, art_url, created_by, created_at, data_origin) VALUES ('reconstructed:kickflip-city', 'kickflip-city', 'Kickflip City', 'PS1', 'Skate', 'Three districts on one board: the civic steps, the market underpass, and the warehouse roofs. Rails, ledges, curb ramps, stair sets and roof gaps, on a 75-second clock per district. Every trick and grind extends an open line and its multiplier, and the line only banks once you settle. Bail and the whole line is gone along with six seconds.', 'Arrows/AD push and brake, Down/S crouch loads a bigger ollie, Space ollies, J kickflip, K heelflip, L grab (hold), Left/Right hold your balance on a grind. P pause, M mute. Touch: brake and push pads left, TRICK and OLLIE right.', 'AI agents', 'A', 'published', 0, 0, 'Score', 80000, NULL, '/assets/games/kickflip-city.png', NULL, '2026-11-08T00:00:00.000Z', 'reconstructed');
INSERT INTO games (id, slug, title, era, genre, description, controls, ai_credit, track, status, featured, play_count, score_label, score_cap, html_path, art_url, created_by, created_at, data_origin) VALUES ('reconstructed:lastwatch', 'lastwatch', 'Lastwatch', 'Original', 'Co-op horde defense', 'The catalog''s 3D flagship: a third-person co-op horde defense. Nine holds kept the line and eight are dark; you and an AI partner hold the ninth through an endless night. Three classes, a five-district hold you open door by door, twelve kinds of Gloam that hunt in packs and dig under your walls, four milestone bosses, and a valor economy of weapons, armor, and timber. The watch holds as long as you do.', 'Keyboard only. WASD moves, mouse aims, LMB attacks (hold to charge or wind up), RMB guards, daggers, or mends by class, Q class skill, E interacts and rebuilds, G bandage, F command wheel, B ledger, P pause, M mute.', 'AI agents', 'A', 'coming_soon', 0, 0, 'Score', 5000000, NULL, '/placeholder.svg', NULL, '2026-11-08T00:00:00.000Z', 'reconstructed');
INSERT INTO games (id, slug, title, era, genre, description, controls, ai_credit, track, status, featured, play_count, score_label, score_cap, html_path, art_url, created_by, created_at, data_origin) VALUES ('reconstructed:munch-maze', 'munch-maze', 'Munch Maze', 'Arcade', 'Maze chase', 'Round creature eating seeds in a hedge maze', 'Arrows or WASD to move; swipe on touch. P pauses, M mutes.', 'AI agents', 'A', 'published', 0, 0, 'Score', 1000000, NULL, '/assets/games/munch-maze.png', NULL, '2026-11-08T00:00:00.000Z', 'reconstructed');
INSERT INTO games (id, slug, title, era, genre, description, controls, ai_credit, track, status, featured, play_count, score_label, score_cap, html_path, art_url, created_by, created_at, data_origin) VALUES ('reconstructed:rockbuster', 'rockbuster', 'Rockbuster', 'Arcade', 'Space shooter', 'Spaceship drifting among tumbling asteroids', 'Arrows or WASD to steer, Space to fire. P pauses, M mutes.', 'AI agents', 'B', 'published', 0, 0, 'Score', 1000000, '/games/rockbuster.html', '/assets/games/rockbuster.png', NULL, '2026-11-08T00:00:00.000Z', 'reconstructed');
INSERT INTO games (id, slug, title, era, genre, description, controls, ai_credit, track, status, featured, play_count, score_label, score_cap, html_path, art_url, created_by, created_at, data_origin) VALUES ('reconstructed:run-n-gunner', 'run-n-gunner', 'Run ''n Gunner', 'NES', 'Run & gun', 'A one-soldier push down Canyon Road and into the Dynamo Core. Three stages of runner bots, turret pods, and mortar lobbers, six bosses that telegraph every volley, three weapon crates worth grabbing, and a score that doubles if you clear the whole campaign without losing a life.', 'Arrows/AD run, W/Up aims up, Space/Z jumps (Down+jump drops through platforms), X/J fires. P pause, M mute. Touch: run pads left, JUMP and FIRE right.', 'AI agents', 'A', 'published', 0, 0, 'Score', 100000, NULL, '/assets/games/run-n-gunner.png', NULL, '2026-11-08T00:00:00.000Z', 'reconstructed');
INSERT INTO games (id, slug, title, era, genre, description, controls, ai_credit, track, status, featured, play_count, score_label, score_cap, html_path, art_url, created_by, created_at, data_origin) VALUES ('reconstructed:rune-ruin', 'rune-ruin', 'Rune & Ruin', 'Original', 'Dungeon crawler', 'Torchlit stone stairwell descending past a glowing runestone', 'Arrows, WASD or vi keys to move; Q uses a tonic. Touch controls are available.', 'AI agents', 'A', 'published', 0, 0, 'Score', 200000, NULL, '/assets/games/rune-ruin.png', NULL, '2026-11-08T00:00:00.000Z', 'reconstructed');
INSERT INTO games (id, slug, title, era, genre, description, controls, ai_credit, track, status, featured, play_count, score_label, score_cap, html_path, art_url, created_by, created_at, data_origin) VALUES ('reconstructed:sky-defense', 'sky-defense', 'Sky Defense', 'Arcade', 'Interception', 'Hold three skylines with one interceptor battery: the Desert Relay, River City, and the Mountain Observatory. Twelve waves send seed pods, clockwork kites, ember mines, balloon decoys, beetle drones, orbiting masks, wind-up swarms, and leaf-sail skiffs down at your towns. Lead your shots, because a burst opens small and grows. Ember mines set off their neighbours, and every kill from one burst scores together.', 'Move the mouse to aim, click to fire. Left/A and Right/D step the aim through eight bearings, Space fires. P pause, M mute. Touch: drag to aim, aim pads left, FIRE right.', 'AI agents', 'A', 'published', 0, 0, 'Score', 60000, NULL, '/assets/games/sky-defense.png', NULL, '2026-11-08T00:00:00.000Z', 'reconstructed');
INSERT INTO games (id, slug, title, era, genre, description, controls, ai_credit, track, status, featured, play_count, score_label, score_cap, html_path, art_url, created_by, created_at, data_origin) VALUES ('reconstructed:starfall-squadron', 'starfall-squadron', 'Starfall Squadron', 'Arcade', 'Space shooter', 'Alien squadron descending toward a lone fighter ship', 'Arrows or AD to move, Space to fire. Touch controls are available. P pauses, M mutes.', 'AI agents', 'A', 'published', 1, 0, 'Score', 1000000, NULL, '/assets/games/starfall-squadron.png', NULL, '2026-11-08T00:00:00.000Z', 'reconstructed');
INSERT INTO games (id, slug, title, era, genre, description, controls, ai_credit, track, status, featured, play_count, score_label, score_cap, html_path, art_url, created_by, created_at, data_origin) VALUES ('reconstructed:the-undervault', 'the-undervault', 'The Undervault', 'Original', 'Dungeon expedition', 'A five floor expedition under a dead city: the Gatehouse, the Ossuary, the Fungal Cistern, the Buried Court, and the Deep Mechanism. Pick one of four delvers at the stair, each with a different edge, then bump-fight your way down through eleven monster families to a keeper who guards every staircase. Each keeper fights its own way, from a colossus that winds up a full turn before it swings to an engine that charges twice and fires down its own row.', 'Arrows/WASD/HJKL step and strike. Q drinks a tonic, G takes what is underfoot, > goes down once the keeper falls, Space waits. P pause, M mute. Touch: D-pad left, TONIC and WAIT right.', 'AI agents', 'A', 'published', 0, 0, 'Score', 60000, NULL, '/assets/games/the-undervault.png', NULL, '2026-11-08T00:00:00.000Z', 'reconstructed');
INSERT INTO games (id, slug, title, era, genre, description, controls, ai_credit, track, status, featured, play_count, score_label, score_cap, html_path, art_url, created_by, created_at, data_origin) VALUES ('reconstructed:trailbound', 'trailbound', 'Trailbound', 'DOS', 'Trail survival', 'Covered wagon crossing the plains toward mountains', 'Use the on-screen choices to manage the journey. P pauses.', 'AI agents', 'B', 'published', 0, 0, 'Score', 1000000, '/games/trailbound.html', '/assets/games/trailbound.png', NULL, '2026-11-08T00:00:00.000Z', 'reconstructed');
